CREATE TABLE `atom` (
  `atom_id` varchar(255) NOT NULL PRIMARY KEY,
  `molecule_id` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  FOREIGN KEY (`molecule_id`) REFERENCES `molecule` (`molecule_id`) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE `bond` (
  `atom_id` varchar(255) NOT NULL,
  `atom_id2` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  PRIMARY KEY (`atom_id`,`atom_id2`),
  FOREIGN KEY (`atom_id`) REFERENCES `atom` (`atom_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (`atom_id2`) REFERENCES `atom` (`atom_id`) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE `gmember` (
  `atom_id` varchar(255) NOT NULL,
  `group_id` varchar(255) NOT NULL,
  PRIMARY KEY (`atom_id`,`group_id`),
  FOREIGN KEY (`atom_id`) REFERENCES `atom` (`atom_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (`group_id`) REFERENCES `group` (`group_id`) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE `group` (
  `group_id` varchar(255) NOT NULL PRIMARY KEY,
  `type` varchar(255) NOT NULL
);
CREATE TABLE `molecule` (
  `molecule_id` varchar(255) NOT NULL PRIMARY KEY,
  `activity` float NOT NULL,
  `logp` float NOT NULL,
  `mweight` float NOT NULL
);
